//! Copies the option table generated by Nix into `OUT_DIR`.
//!
//! The table lives in `assets/syncthing-options.nix` and is generated by
//! `nix/scripts/gen-syncthing-options.py`. This build script does NOT generate
//! it — it only locates the finished file. Generating here would reimplement
//! Nix logic (invariant 5) and would leave the source of truth.
//!
//! The same shape as `ronoctua-audio`'s build script, down to the reason the
//! destination is deleted first.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_SYNCTHING_OPTIONS_RS");

    let generated = env::var("RONOCTUA_SYNCTHING_OPTIONS_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_SYNCTHING_OPTIONS_RS is not set.\n\
             \n\
             The Syncthing option table is generated by Nix out of\n\
             assets/syncthing-options.nix. Enter the environment with `direnv allow`\n\
             (or `nix develop`), which sets the variable, or build through the flake\n\
             with `nix build`.\n\
             \n\
             Generating the table here would reimplement Nix logic (invariant 5)."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("options.rs");
    // DELETE FIRST. The file comes from the store and carries its read-only
    // mode with it; on the second generation `fs::copy` would fail with
    // "Permission denied" inside a build script.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
